function prefix_function(s):
  pi[0..n-1]=0
  for i in 1..n-1:
    j = pi[i-1]
    while j>0 and s[i]!=s[j]: j = pi[j-1]
    if s[i]==s[j]: j += 1
    pi[i] = j
  return pi

function kmp_match(text, pattern):
  cur = pattern + '#' + text
  pi = prefix_function(cur)
  for i in |pattern|+1 .. |cur|-1:
    if pi[i]==|pattern|: record i - 2*|pattern|
